function CodeFrame({children}:any){
 const [lineNumbers,setLineNumbers]=useState(false)
 const node=isValidElement(children)?children:null
 const props=(node?.props||{}) as any
 const toText=(value:any):string=>Array.isArray(value)?value.map(toText).join(''):typeof value==='string'||typeof value==='number'?String(value):value?.props?.children!==undefined?toText(value.props.children):'';const source=toText(props.children).replace(/\n$/,'')
 const language=String(props.className||'').match(/language-([\w-]+)/)?.[1]||'代码'
 const lines=source.split('\n')
 return <section className="code-frame"><header className="code-toolbar"><span className="code-language">{language}</span><span className="code-toolbar-actions">{(/^(html|htm)$/i.test(language)||/<html[\s>]|<body[\s>]|<!doctype html/i.test(source))&&<button type="button" onClick={()=>window.dispatchEvent(new CustomEvent('myagent:open-canvas',{detail:{title:'AI 代码预览',html:source}}))} title="在画布中预览"><Globe2 size={13}/>画布</button>}<button type="button" onClick={()=>setLineNumbers(v=>!v)} title="切换行号">{lineNumbers?'隐藏行号':'显示行号'}</button><button type="button" onClick={()=>void navigator.clipboard.writeText(source)} title="复制代码"><Copy size={13}/>复制</button></span></header><div className="code-scroll">{lineNumbers&&<div className="code-line-numbers" aria-hidden="true">{lines.map((_,i)=><span key={i}>{i+1}</span>)}</div>}<pre>{node?cloneElement(node as any,{className:props.className}):<code>{source}</code>}</pre></div></section>
}
type WorkPaneKind = 'notes' | 'code' | 'terminal' | 'file' | 'image' | 'canvas'
type WorkPane = { id:string; title:string; kind:WorkPaneKind; content:string; src?:string; path?:string; html?:string }
type WorkbenchProps = { theme:string; onThemeChange:(value:string)=>void; onClose:()=>void }
const Workbench=memo(function Workbench({theme,onThemeChange,onClose}:WorkbenchProps) {
 const [panes,setPanes]=useState<WorkPane[]>([{id:'welcome',title:'工作区概览',kind:'notes',content:'在这里整理当前任务。\n\n可以添加笔记、代码草稿、终端输出或文件预览。'}])
 const [layout,setLayout]=useState<'one'|'columns'|'rows'|'grid'>(()=>{try{return (localStorage.getItem('myagent:workbench-layout') as any)||'one'}catch{return 'one'}})
 const [split,setSplit]=useState(()=>{try{return Math.max(25,Math.min(75,Number(localStorage.getItem('myagent:workbench-split')||50)))}catch{return 50}})
 const gridRef=useRef<HTMLDivElement|null>(null)
 const [maximized,setMaximized]=useState<string|null>(null)
 const [activePaneId,setActivePaneId]=useState('welcome')
 const [splitY,setSplitY]=useState(()=>{try{return Math.max(25,Math.min(75,Number(localStorage.getItem('myagent:workbench-split-y')||50)))}catch{return 50}})
 const [dragging,setDragging]=useState<string|null>(null)
 const [dropTarget,setDropTarget]=useState<string|null>(null)
 const fileRef=useRef<HTMLInputElement|null>(null)
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('myagent:workbench-panes')||'[]');if(Array.isArray(saved)&&saved.length){setPanes(saved.map((p:any)=>({id:String(p.id),title:String(p.title),kind:p.kind as WorkPaneKind,content:'',path:p.path?String(p.path):undefined})))}}catch{}},[])
 useEffect(()=>{try{localStorage.setItem('myagent:workbench-layout',layout);localStorage.setItem('myagent:workbench-split',String(split));localStorage.setItem('myagent:workbench-split-y',String(splitY));localStorage.setItem('myagent:workbench-panes',JSON.stringify(panes.filter(p=>p.kind!=='image').map(({id,title,kind,path})=>({id,title,kind,path}))))}catch{}},[layout,panes,split,splitY])
 useEffect(()=>{const onFile=(event:Event)=>{const detail=(event as CustomEvent<{name:string;path?:string;content:string;src?:string}>).detail;if(!detail)return;const id='file-'+Date.now();setPanes(prev=>[{id,title:detail.name,kind:detail.src?'image':'file',content:detail.content,src:detail.src,path:detail.path||detail.name},...prev]);setActivePaneId(id);setMaximized(null)};const onTerminal=(event:Event)=>{const detail=(event as CustomEvent<{text:string}>).detail;if(!detail?.text)return;setPanes(prev=>{const index=prev.findIndex(p=>p.kind==='terminal');if(index<0)return [{id:'terminal-'+Date.now(),title:'工具输出',kind:'terminal',content:detail.text},...prev];return prev.map((p,i)=>i===index?{...p,content:(p.content?p.content+'\n':'')+detail.text}:p)})};window.addEventListener('myagent:open-file',onFile);window.addEventListener('myagent:terminal-output',onTerminal);return()=>{window.removeEventListener('myagent:open-file',onFile);window.removeEventListener('myagent:terminal-output',onTerminal)}},[])
 useEffect(()=>{const onCanvas=(event:Event)=>{const detail=(event as CustomEvent<{title?:string;html?:string}>).detail;const id='canvas-'+Date.now();setPanes(prev=>[{id,title:detail?.title||'HTML 画布',kind:'canvas',content:'',html:detail?.html||''},...prev]);setActivePaneId(id);setLayout('one');setMaximized(null)};window.addEventListener('myagent:open-canvas',onCanvas);return()=>window.removeEventListener('myagent:open-canvas',onCanvas)},[])
 const addPane=(kind:Exclude<WorkPaneKind,'image'>)=>{const titles={notes:'新建笔记',code:'代码草稿',terminal:'终端输出',file:'文件预览',canvas:'HTML 画布'},id=kind+'-'+Date.now();setPanes(prev=>[{id,title:titles[kind],kind,content:kind==='terminal'?'等待工具输出…\n此区域用于展示输出，不会在浏览器中执行命令。':''},...prev]);setActivePaneId(id);setMaximized(null)}
 const changeLayout=(next:'one'|'columns'|'rows'|'grid')=>{setLayout(next);const count=next==='grid'?4:next==='one'?1:2;setPanes(prev=>{const nextPanes=[...prev];while(nextPanes.length<count)nextPanes.push({id:'pane-'+Date.now()+'-'+nextPanes.length,title:'新窗格',kind:'notes',content:''});return nextPanes})}
 const updatePane=(id:string,content:string)=>setPanes(prev=>prev.map(p=>p.id===id?{...p,content}:p))
 const closePane=(id:string)=>{const pane=panes.find(p=>p.id===id);if(pane?.src)URL.revokeObjectURL(pane.src);setPanes(prev=>prev.filter(p=>p.id!==id));if(maximized===id)setMaximized(null);if(activePaneId===id)setActivePaneId(panes.find(p=>p.id!==id)?.id||'')}
 const reorder=(from:string,to:string)=>{if(from===to)return;setPanes(prev=>{const next=[...prev],a=next.findIndex(p=>p.id===from),b=next.findIndex(p=>p.id===to);if(a<0||b<0)return prev;const [item]=next.splice(a,1);next.splice(b,0,item);return next})}
 const beginSplit=(event:ReactPointerEvent<HTMLDivElement>,axis:'x'|'y')=>{event.preventDefault();document.body.classList.add('myagent-resizing');const start=axis==='x'?event.clientX:event.clientY;const parent=gridRef.current;if(!parent)return;const rect=parent.getBoundingClientRect(),size=axis==='x'?rect.width:rect.height,initial=axis==='x'?split:splitY;let next=initial;const move=(e:PointerEvent)=>{const point=axis==='x'?e.clientX:e.clientY;next=Math.max(25,Math.min(75,initial+(point-start)/size*100));if(axis==='x')parent.style.gridTemplateColumns='minmax(0,'+next+'fr) 6px minmax(0,'+(100-next)+'fr)';else parent.style.gridTemplateRows='minmax(0,'+next+'fr) 6px minmax(0,'+(100-next)+'fr)'};const up=()=>{document.body.classList.remove('myagent-resizing');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);if(axis==='x')setSplit(next);else setSplitY(next)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});window.addEventListener('pointercancel',up,{once:true})}
 const visible=maximized?panes.filter(p=>p.id===maximized):layout==='one'?panes.filter(p=>p.id===activePaneId).slice(0,1):panes.slice(0,layout==='grid'?4:2)
 const gridStyle:CSSProperties={gridTemplateColumns:layout==='columns'?'minmax(0,'+split+'fr) 6px minmax(0,'+(100-split)+'fr)':layout==='grid'?'minmax(0,'+split+'fr) 6px minmax(0,'+(100-split)+'fr)':'minmax(0,1fr)',gridTemplateRows:layout==='rows'?'minmax(0,'+splitY+'fr) 6px minmax(0,'+(100-splitY)+'fr)':layout==='grid'?'minmax(0,'+splitY+'fr) 6px minmax(0,'+(100-splitY)+'fr)':'minmax(0,1fr)'}
 return <aside className="workbench" aria-label="多窗格工作区">
  <div className="workbench-toolbar"><div className="workbench-heading"><LayoutGrid size={16}/><b>工作区画布</b><span>{panes.length} 个窗格</span></div><div className="workbench-actions"><button title="新建 HTML 画布" onClick={()=>window.dispatchEvent(new CustomEvent('myagent:open-canvas',{detail:{}}))}><Globe2 size={15}/></button><button title="添加笔记" onClick={()=>addPane('notes')}><FileText size={15}/></button><button title="添加代码草稿" onClick={()=>addPane('code')}><Code2 size={15}/></button><button title="添加终端输出区" onClick={()=>addPane('terminal')}><Terminal size={15}/></button><button title="打开文件" onClick={()=>fileRef.current?.click()}><Paperclip size={15}/></button><input ref={fileRef} type="file" hidden onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(file.type.startsWith('image/')){const src=URL.createObjectURL(file),id='image-'+Date.now();setPanes(prev=>[{id,title:file.name,kind:'image',content:'',src},...prev]);setActivePaneId(id)}else{const content=await file.text().catch(()=>'无法读取该文件预览'),id='file-'+Date.now();setPanes(prev=>[{id,title:file.name,kind:'file',content},...prev]);setActivePaneId(id)}e.target.value=''}}/></div><div className="workbench-layouts"><button className={layout==='one'?'active':''} title="单窗格" onClick={()=>changeLayout('one')}><Square size={14}/></button><button className={layout==='columns'?'active':''} title="左右两列" onClick={()=>changeLayout('columns')}><Columns2 size={14}/></button><button className={layout==='rows'?'active':''} title="上下两行" onClick={()=>changeLayout('rows')}><Rows2 size={14}/></button><button className={layout==='grid'?'active':''} title="2×2" onClick={()=>changeLayout('grid')}><Grid2X2 size={14}/></button></div><button className="workbench-theme" title="切换主题" onClick={()=>onThemeChange(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={15}/>:<Moon size={15}/>}</button><button className="workbench-close" title="收起工作区" onClick={onClose}><PanelRightClose size={16}/></button></div>
  <div className="workbench-tabs">{panes.map(p=><button key={p.id} draggable onDragStart={e=>e.dataTransfer.setData('text/plain',p.id)} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();reorder(e.dataTransfer.getData('text/plain'),p.id)}} className={activePaneId===p.id?'active':''} onClick={()=>{setActivePaneId(p.id);if(layout==='one')setMaximized(null);else setPanes(prev=>{const index=prev.findIndex(x=>x.id===p.id);if(index<0||index<(layout==='grid'?4:2))return prev;const next=[...prev],picked=next.splice(index,1)[0];next.unshift(picked);return next})}} title={p.path||p.title}><span>{p.path||p.title}</span><i onClick={e=>{e.stopPropagation();closePane(p.id)}}>×</i></button>)}</div>
  <div ref={gridRef} className={'workbench-grid layout-'+layout+(maximized?' is-maximized':'')} style={gridStyle}>
   {(layout==='rows'||layout==='grid')&&!maximized&&<div className="pane-splitter horizontal" role="separator" aria-label="调整窗格高度" onPointerDown={e=>beginSplit(e,'y')}/>}
   {(layout==='columns'||layout==='grid')&&!maximized&&<div className="pane-splitter vertical" role="separator" aria-label="调整窗格宽度" onPointerDown={e=>beginSplit(e,'x')}/>}
   {visible.map((pane,index)=><Fragment key={pane.id}>
    <section className={'work-pane '+(dropTarget===pane.id?'drop-target':'')} draggable={!maximized} onDragStart={e=>{setDragging(pane.id);e.dataTransfer.setData('text/plain',pane.id)}} onDragOver={e=>{e.preventDefault();setDropTarget(pane.id)}} onDragLeave={()=>setDropTarget(null)} onDrop={e=>{e.preventDefault();reorder(e.dataTransfer.getData('text/plain')||dragging||'',pane.id);setDragging(null);setDropTarget(null)}} onDragEnd={()=>{setDragging(null);setDropTarget(null)}}>
     <header className="work-pane-header"><span className="pane-grip" title="拖动重排"><GripVertical size={14}/></span><span className="pane-kind-icon">{pane.kind==='terminal'?<Terminal size={14}/>:pane.kind==='code'?<Code2 size={14}/>:(pane.kind==='file'||pane.kind==='image')?<FileImage size={14}/>:<FileText size={14}/>}</span><b title={pane.path||pane.title}>{pane.title}</b><button title={maximized===pane.id?'还原窗格':'最大化'} onClick={()=>{setActivePaneId(pane.id);setMaximized(maximized===pane.id?null:pane.id)}}><Maximize2 size={13}/></button><button title="关闭窗格" onClick={()=>closePane(pane.id)}><X size={14}/></button></header>
     <div className="work-pane-body">{pane.kind==='canvas'?<CanvasPane html={pane.html||''} onChange={value=>setPanes(prev=>prev.map(item=>item.id===pane.id?{...item,html:value}:item))}/>:pane.kind==='terminal'?<pre className="terminal-output">{pane.content||'终端输出区域\n\n工具执行结果会显示在这里。浏览器不会直接执行系统命令。'}</pre>:pane.kind==='file'?<pre className="file-preview">{pane.content||'文件内容为空'}</pre>:pane.kind==='image'?<div className="image-preview"><img src={pane.src} alt={pane.title}/></div>:<textarea aria-label={pane.title} value={pane.content} onChange={e=>updatePane(pane.id,e.target.value)} placeholder={pane.kind==='code'?'在这里编写代码草稿…':'在这里记录想法、计划或摘要…'} spellCheck={false}/>}</div>
    </section>
   </Fragment>)}
   {!maximized&&visible.length===0&&<div className="workbench-empty"><LayoutGrid size={24}/><b>画布已清空</b><span>从上方工具栏添加一个窗格，或新建 HTML 画布预览 AI 生成的网页。</span><button className="workbench-empty-action" onClick={()=>window.dispatchEvent(new CustomEvent('myagent:open-canvas',{detail:{}}))}><Globe2 size={14}/>新建 HTML 画布</button></div>}
  </div>
 </aside>
})

