 async function refreshChats(workspaceId:string|null,selectFirst=true){
  loadedChatRef.current=null
  const url=workspaceId?'/api/chats?workspaceId='+encodeURIComponent(workspaceId):'/api/chats'
  const r=await fetch(url)
  if(!r.ok)throw new Error('读取聊天记录失败（HTTP '+r.status+'）')
  const d=await r.json()
  const list:Chat[]=(d.chats||[]).map((c:any)=>({id:String(c.id),title:c.title,group:'最近',workspaceId:c.workspaceId,updatedAt:c.updatedAt}))
  setChats(list)
  if(selectFirst){const first=list[0];setChat(first?.id||null);setMessages([]);loadedChatRef.current=null;activeChatRef.current=first?.id||null;if(first){const detail=await fetch('/api/chats/'+encodeURIComponent(first.id));if(detail.ok){const data=await detail.json();if(activeChatRef.current===first.id){setMessages(Array.isArray(data.chat?.data)?data.chat.data:[]);loadedChatRef.current=first.id}}}}
  return list
 }
