 async function createChat(){followLatestRef.current=true;setShowJumpToLatest(false);if(!authUser)throw new Error('登录状态已失效，请重新登录。');const id=globalThis.crypto?.randomUUID?.()||('chat-'+Date.now()+'-'+Math.random().toString(36).slice(2));const workspaceId=activeWorkspaceId;const r=await fetch('/api/chats/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({title:'新的对话',data:[],workspaceId})});const raw=await r.text();let d:any={};try{d=JSON.parse(raw)}catch{}if(!r.ok)throw new Error(d.error||'新建对话失败（HTTP '+r.status+'）');loadedChatRef.current=id;activeChatRef.current=id;setChat(id);setMessages([]);setChats(prev=>[{id,title:'新的对话',group:'最近',workspaceId},...prev.filter(x=>x.id!==id)]);return id}
