 async function openChat(id:string){if(typeof window!=='undefined'&&window.innerWidth<=760)setLeft(false);followLatestRef.current=true;setShowJumpToLatest(false);loadedChatRef.current=null;activeChatRef.current=id;setChat(id);setMessages([]);try{const r=await fetch('/api/chats/'+encodeURIComponent(id));if(!r.ok)throw new Error('读取会话失败');const d=await r.json();if(activeChatRef.current!==id)return;setMessages(Array.isArray(d.chat?.data)?d.chat.data:[]);loadedChatRef.current=id}catch(e){showToast(e instanceof Error?e.message:'读取聊天记录失败');loadedChatRef.current=null}}
 async function deleteChat(id:string){if(!window.confirm('确定删除这段聊天记录吗？删除后无法恢复。'))return;if(id===chat){loadedChatRef.current=null;activeChatRef.current=null;}try{const r=await fetch('/api/chats/'+encodeURIComponent(id),{method:'DELETE'});if(!r.ok)throw new Error('删除失败');const rest=chats.filter(c=>c.id!==id);setChats(rest);if(chat===id){setChat(null);setMessages([]);if(rest[0])await openChat(rest[0].id)}showToast('聊天记录已删除。')}catch(e){showToast(e instanceof Error?e.message:'删除失败')}}
