 async function createWorkspace(){if(workspaceName.trim().length<2){showToast('工作区名称至少需要 2 个字符。');return}setWorkspaceBusy(true);try{const r=await fetch('/api/workspaces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:workspaceName,description:workspaceDescription})});const d=await r.json();if(!r.ok)throw new Error(d.error||'创建工作区失败');const list=[d.workspace,...workspaces];setWorkspaces(list);setWorkspaceName('');setWorkspaceDescription('');setActiveWorkspaceId(d.workspace.id);loadedChatRef.current=null;setModal(null);await refreshChats(d.workspace.id);showToast('工作区已创建。它不会自动新建聊天。')}catch(e){showToast(e instanceof Error?e.message:'创建工作区失败')}finally{setWorkspaceBusy(false)}}
