 async function saveVoiceConfig(patch:any){const next={...voiceConfig,...patch};setVoiceConfig(next);try{const r=await fetch('/api/voice/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)}),d=await r.json();if(!r.ok)throw new Error(d.error||'配置保存失败');setVoiceConfig(d.config)}catch(error){setVoiceError(error instanceof Error?error.message:'配置保存失败')}}
